using FluentValidation;using Microsoft.EntityFrameworkCore;using SchoolERP.Application.Abstractions;using SchoolERP.Application.Common.Extensions;using SchoolERP.Application.Common.Pagination;using SchoolERP.Application.Exceptions;using SchoolERP.Application.Features.Schools;using SchoolERP.Domain.Entities;using SchoolERP.Domain.Enums;
namespace SchoolERP.Application.Features.SchoolClasses;public sealed class SchoolClassService(IApplicationDbContext db,ICurrentSchoolResolver current,IValidator<CreateSchoolClassRequest>cv,IValidator<UpdateSchoolClassRequest>uv,IValidator<ChangeSchoolClassCodeRequest>ccv,TimeProvider clock):ISchoolClassService{
 public async Task<PagedResult<SchoolClassListItemDto>>ListAsync(GetSchoolClassesQuery r,CancellationToken ct=default){var sid=await current.ResolveAsync(ct);if(r.AcademicYearId.HasValue&&!await db.AcademicYears.AsNoTracking().AnyAsync(x=>x.Id==r.AcademicYearId&&x.SchoolId==sid,ct))throw new ResourceNotFoundException("Academic year");var q=db.SchoolClasses.AsNoTracking().Where(x=>x.SchoolId==sid).WhereIf(r.AcademicYearId.HasValue,x=>x.AcademicYearId==r.AcademicYearId).WhereIf(r.Status.HasValue,x=>x.Status==r.Status).WhereIf(r.EducationLevel.HasValue,x=>x.EducationLevel==r.EducationLevel);if(!string.IsNullOrWhiteSpace(r.Search)){var t=r.Search.Trim().ToLower();q=q.Where(x=>x.Name.ToLower().Contains(t)||x.Code.ToLower().Contains(t)||(x.ShortName!=null&&x.ShortName.ToLower().Contains(t)));}var desc=string.Equals(r.SortDirection,"desc",StringComparison.OrdinalIgnoreCase);q=(r.SortBy?.ToLowerInvariant(),desc) switch{("name",false)=>q.OrderBy(x=>x.Name),("name",true)=>q.OrderByDescending(x=>x.Name),("code",false)=>q.OrderBy(x=>x.Code),("code",true)=>q.OrderByDescending(x=>x.Code),("status",false)=>q.OrderBy(x=>x.Status),("status",true)=>q.OrderByDescending(x=>x.Status),("createdat",false)=>q.OrderBy(x=>x.CreatedAt),("createdat",true)=>q.OrderByDescending(x=>x.CreatedAt),(_,true)=>q.OrderByDescending(x=>x.DisplayOrder).ThenByDescending(x=>x.Name),_=>q.OrderBy(x=>x.DisplayOrder).ThenBy(x=>x.Name)};return await q.Select(x=>new SchoolClassListItemDto(x.Id,x.AcademicYearId,x.AcademicYear.Name,x.Name,x.Code,x.ShortName,x.DisplayOrder,x.EducationLevel,x.Status,x.CreatedAt,x.UpdatedAt)).ToPagedResultAsync(new(r.PageNumber,r.PageSize),ct);}
 public async Task<SchoolClassDetailsDto?>GetAsync(Guid id,CancellationToken ct=default){var sid=await current.ResolveAsync(ct);return await db.SchoolClasses.AsNoTracking().Where(x=>x.Id==id&&x.SchoolId==sid).Select(x=>new SchoolClassDetailsDto(x.Id,x.AcademicYearId,x.AcademicYear.Name,x.AcademicYear.Code,x.Name,x.Code,x.ShortName,x.DisplayOrder,x.EducationLevel,x.Status,x.Description,x.ActivatedAt,x.DeactivatedAt,x.ArchivedAt,x.CreatedAt,x.UpdatedAt)).SingleOrDefaultAsync(ct);}
 public async Task<SchoolClassDetailsDto>CreateAsync(CreateSchoolClassRequest r,CancellationToken ct=default){await cv.ValidateAndThrowAsync(r,ct);var sid=await current.ResolveAsync(ct);var school=await db.Schools.AsNoTracking().SingleAsync(x=>x.Id==sid,ct);if(school.Status is SchoolStatus.Suspended or SchoolStatus.Archived)throw new ParentNotOperationalException("School structure cannot be changed while suspended or archived.");var year=await db.AcademicYears.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==r.AcademicYearId&&x.SchoolId==sid,ct)??throw new ResourceNotFoundException("Academic year");if(year.Status is AcademicYearStatus.Closed or AcademicYearStatus.Archived)throw new SchoolClassParentUnavailableException();var code=SchoolClass.NormalizeCode(r.Code);await Unique(sid,r.AcademicYearId,code,null,ct);var x=SchoolClass.Create(school.TenantId,sid,r.AcademicYearId,r.Name,code,r.DisplayOrder,r.ShortName,r.EducationLevel,r.Description,Now());db.SchoolClasses.Add(x);await db.SaveChangesAsync(ct);return(await GetAsync(x.Id,ct))!;}
 public async Task<SchoolClassDetailsDto?>UpdateAsync(Guid id,UpdateSchoolClassRequest r,CancellationToken ct=default){await uv.ValidateAndThrowAsync(r,ct);var x=await Write(id,ct);if(x is null)return null;await Parent(x,ct);x.UpdateDetails(r.Name,r.ShortName,r.DisplayOrder,r.EducationLevel,r.Description,Now());await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}
 public async Task<SchoolClassDetailsDto?>ChangeCodeAsync(Guid id,ChangeSchoolClassCodeRequest r,CancellationToken ct=default){await ccv.ValidateAndThrowAsync(r,ct);var x=await Write(id,ct);if(x is null)return null;await Parent(x,ct);var c=SchoolClass.NormalizeCode(r.Code);await Unique(x.SchoolId,x.AcademicYearId,c,id,ct);x.ChangeCode(c,Now());await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}
 public Task<SchoolClassDetailsDto?>ActivateAsync(Guid id,CancellationToken ct=default)=>Change(id,(x,n)=>x.Activate(n),ct);public Task<SchoolClassDetailsDto?>DeactivateAsync(Guid id,CancellationToken ct=default)=>Change(id,(x,n)=>x.Deactivate(n),ct);public Task<SchoolClassDetailsDto?>ArchiveAsync(Guid id,CancellationToken ct=default)=>Change(id,(x,n)=>x.Archive(n),ct);
 private async Task<SchoolClassDetailsDto?>Change(Guid id,Action<SchoolClass,DateTime>a,CancellationToken ct){var x=await Write(id,ct);if(x is null)return null;await Parent(x,ct);a(x,Now());await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}private async Task<SchoolClass?>Write(Guid id,CancellationToken ct){var sid=await current.ResolveAsync(ct);return await db.SchoolClasses.SingleOrDefaultAsync(x=>x.Id==id&&x.SchoolId==sid,ct);}private async Task Parent(SchoolClass x,CancellationToken ct){var schoolOk=await db.Schools.AsNoTracking().AnyAsync(s=>s.Id==x.SchoolId&&(s.Status==SchoolStatus.Draft||s.Status==SchoolStatus.Active),ct);var yearOk=await db.AcademicYears.AsNoTracking().AnyAsync(y=>y.Id==x.AcademicYearId&&y.SchoolId==x.SchoolId&&(y.Status==AcademicYearStatus.Draft||y.Status==AcademicYearStatus.Active),ct);if(!schoolOk)throw new ParentNotOperationalException("School structure cannot be changed while suspended or archived.");if(!yearOk)throw new SchoolClassParentUnavailableException();}private async Task Unique(Guid s,Guid y,string c,Guid? except,CancellationToken ct){if(await db.SchoolClasses.AsNoTracking().AnyAsync(x=>x.SchoolId==s&&x.AcademicYearId==y&&x.Code==c&&(!except.HasValue||x.Id!=except),ct))throw new SchoolClassCodeConflictException();}private DateTime Now()=>clock.GetUtcNow().UtcDateTime;}
